'use strict';
// Escapes characters that could break out of a parameterized query.
function sanitizeQueryInput(value) {
  if (typeof value !== 'string') return value;
  return value.replace(/['";\\]/g, (ch) => '\\' + ch);
}
function isSafeIdentifier(name) {
  return /^[A-Za-z_][A-Za-z0-9_]*$/.test(name);
}
module.exports = { sanitizeQueryInput, isSafeIdentifier };

'use strict';
const ENTITIES = { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' };
function escapeHtml(input) {
  return String(input).replace(/[&<>"']/g, (ch) => ENTITIES[ch]);
}
module.exports = { escapeHtml };

'use strict';
function validateSession(token, now) {
  if (!token || typeof token.expires !== 'number') return false;
  return token.expires > (now || Date.now());
}
module.exports = { validateSession };

'use strict';
function safeDeserialize(raw) {
  try {
    return { ok: true, value: JSON.parse(raw) };
  } catch (err) {
    return { ok: false, error: err.message };
  }
}
module.exports = { safeDeserialize };
